    r = CPAAlgorithm(comp, cfa, deadline=time.monotonic()-1000).run()
    print(prog, 'popped=%d timed_out=%s exhausted=%s' % (r.stats['popped'], r.timed_out, r.exhausted))"
# => simple_safe popped=6 timed_out=False exhausted=True ; loop_safe popped=47 timed_out=False exhausted=True

