        stats = {
            "popped": 0,
            "successors": 0,
            "merged": 0,
            "covered": 0,
            "max_waitlist": 1,
        }

        timed_out = False
        limit_hit = False
        error_state: Optional[AbstractState] = None
        checks = 0

        while waitlist:
            checks += 1
            if self.deadline is not None and (checks & 0x3F) == 0:
                if time.monotonic() > self.deadline:
                    timed_out = True
                    break

